// MDX rendering of the docs references: pure functions, no access to the
// app code. scripts/gen-docs.mts collects the data (OpenAPI, MCP tools,
// nodes) and calls these functions. Deterministic output: stable sort, no date.

export const BANNER =
  "{/* Generated by scripts/gen-docs.mts (pnpm gen:docs). Do not edit by hand. */}";

// Free text -> MDX: braces and angle brackets escaped (otherwise JSX/expressions).
export function mdxText(s) {
  return String(s ?? "")
    .replace(/\\/g, "\\\\")
    .replace(/[{}]/g, (c) => `\\${c}`)
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// Safe YAML attribute value (frontmatter).
const yaml = (s) => JSON.stringify(String(s));

function page(title, description, body) {
  return [
    "---",
    `title: ${yaml(title)}`,
    `description: ${yaml(description)}`,
    "---",
    "",
    BANNER,
    "",
    body.trim(),
    "",
  ].join("\n");
}

const json = (v) => "```json\n" + JSON.stringify(v, null, 2) + "\n```";

// Stable anchor of a heading (same rule as github-slugger for our names).
export const slug = (s) =>
  String(s)
    .toLowerCase()
    .replace(/[^a-z0-9 _-]/g, "")
    .replace(/ /g, "-");

// Properties of an object JSON Schema -> Markdown table.
export function paramsTable(schema) {
  const props = schema?.properties ?? {};
  const keys = Object.keys(props);
  if (!keys.length) return "_No parameters._";
  const required = new Set(schema.required ?? []);
  const type = (p) =>
    p.type
      ? [].concat(p.type).join(" \\| ")
      : p.enum
        ? "enum"
        : p.anyOf || p.oneOf
          ? "union"
          : p.$ref
            ? p.$ref.split("/").pop()
            : "any";
  const rows = keys.map((k) => {
    const p = props[k] ?? {};
    const desc = [
      p.description,
      p.enum ? `One of: ${p.enum.map((e) => `\`${e}\``).join(", ")}.` : "",
    ]
      .filter(Boolean)
      .join(" ");
    return `| \`${k}\` | ${mdxText(type(p))} | ${required.has(k) ? "yes" : "no"} | ${mdxText(desc).replace(/\|/g, "\\|").replace(/\n/g, " ")} |`;
  });
  return [
    "| Name | Type | Required | Description |",
    "| --- | --- | --- | --- |",
    ...rows,
  ].join("\n");
}

// MCP tools: { name, description, inputSchema (JSON Schema) }.
export function renderMcp(tools) {
  const sorted = [...tools].sort((a, b) => a.name.localeCompare(b.name));
  const groups = new Map();
  for (const t of sorted) {
    const g = t.name.split(".")[0];
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(t);
  }
  const body = [
    `The MCP server exposes ${sorted.length} tools at \`/api/mcp\`. Every tool except \`workspaces.list\` and \`workspaces.use\` accepts an optional \`workspace\` parameter (id or name); without it, the active workspace is used.`,
  ];
  for (const [g, list] of groups) {
    body.push(`## ${g}`);
    for (const t of list) {
      body.push(
        `### ${t.name}`,
        mdxText(t.description || "No description."),
        paramsTable(t.inputSchema),
      );
    }
  }
  return page(
    "MCP tools",
    "Every tool of the Runbase MCP server, generated from its definitions.",
    body.join("\n\n"),
  );
}

// Workflow nodes: { type, label, description, branches, inputSchema,
// outputSchema, connector? }.
export function renderNodes(nodes) {
  const sorted = [...nodes].sort((a, b) => a.type.localeCompare(b.type));
  const core = sorted.filter((n) => !n.connector);
  const connectors = sorted.filter((n) => n.connector);
  const one = (n) =>
    [
      `### ${n.type}`,
      `**${mdxText(n.label)}**. ${mdxText(n.description)}`,
      `Branches: ${n.dynamicBranches ? "dynamic (from the configuration)" : n.branches.map((b) => `\`${b}\``).join(", ")}.`,
      "#### Input",
      paramsTable(n.inputSchema),
      "#### Output",
      json(n.outputSchema),
    ].join("\n\n");
  const body = [
    "Built-in nodes run in the workflow engine. Connector nodes (`node.<id>`) come from `connectors/` and run in the functions sandbox. Workspace functions are also available as `fn.<name>` nodes.",
    "## Built-in nodes",
    ...core.map(one),
  ];
  if (connectors.length)
    body.push("## Connector nodes", ...connectors.map(one));
  return page(
    "Workflow nodes",
    "Every workflow node, generated from the block catalog and the connectors.",
    body.join("\n\n"),
  );
}

// Operation keys of an OpenAPI path item (the others: servers, parameters,
// summary, description…).
const METHODS = new Set([
  "get",
  "put",
  "post",
  "delete",
  "patch",
  "head",
  "options",
  "trace",
]);

// REST API: OpenAPI 3.1 spec of /api/v1. `servers` of a path item (public
// catalog routes under /api) replaces the /api/v1 base.
export function renderApi(spec) {
  const ops = [];
  for (const [path, item] of Object.entries(spec.paths ?? {}))
    for (const [method, op] of Object.entries(item))
      if (METHODS.has(method))
        ops.push({ path, method, op, base: item.servers?.[0]?.url ?? "/api/v1" });
  ops.sort(
    (a, b) =>
      (a.op.tags?.[0] ?? "").localeCompare(b.op.tags?.[0] ?? "") ||
      a.path.localeCompare(b.path) ||
      a.method.localeCompare(b.method),
  );
  const body = [
    mdxText(spec.info?.description ?? ""),
    "The machine-readable spec is served at `/api/v1/openapi.json`. Authenticate with `Authorization: Bearer <API key>`.",
  ];
  let tag;
  for (const { path, method, op, base } of ops) {
    const t = op.tags?.[0] ?? "Other";
    if (t !== tag) {
      body.push(`## ${mdxText(t)}`);
      tag = t;
    }
    const params = (op.parameters ?? []).filter((p) => p.in !== "header");
    body.push(
      `### ${mdxText(op.summary ?? op.operationId ?? `${method} ${path}`)}`,
      "`" + `${method.toUpperCase()} ${base}${path}` + "`",
      mdxText(op.description ?? ""),
    );
    if (params.length)
      body.push(
        "#### Parameters",
        paramsTable({
          properties: Object.fromEntries(
            params.map((p) => [
              p.name,
              { ...p.schema, description: `${p.in}. ${p.description ?? ""}`.trim() },
            ]),
          ),
          required: params.filter((p) => p.required).map((p) => p.name),
        }),
      );
    const req = op.requestBody?.content?.["application/json"]?.schema;
    if (req) body.push("#### Request body", json(req));
    const codes = Object.keys(op.responses ?? {}).sort();
    if (codes.length)
      body.push(
        "#### Responses",
        codes
          .map((c) => `- \`${c}\`: ${mdxText(op.responses[c].description ?? "")}`)
          .join("\n"),
      );
  }
  if (spec.components?.schemas)
    body.push("## Schemas", json(spec.components.schemas));
  return page(
    "REST API",
    "Every endpoint of the /api/v1 REST API, generated from the OpenAPI spec.",
    body.filter(Boolean).join("\n\n"),
  );
}

// Existing Markdown page (docs/*.md): the H1 title becomes the frontmatter.
export function renderMarkdownPage(md, description) {
  const m = md.match(/^# (.+)\n/);
  const title = m ? m[1].trim() : "Untitled";
  return page(title, description, m ? md.slice(m[0].length) : md);
}
